// 由 Report Skill 注入：占位符必须且仅出现一次
const reportData = __REPORT_DATA__;

/* ── 工具函数 ── */
function asString(value, fallback = '-') {
  if (value == null) return fallback;
  const text = String(value).trim();
  return text === '' ? fallback : text;
}

function safeArray(value) {
  return Array.isArray(value) ? value : [];
}

function setText(id, value, fallback = '-') {
  const node = document.getElementById(id);
  if (node) node.textContent = asString(value, fallback);
}

function setHTML(id, html) {
  const node = document.getElementById(id);
  if (node) node.innerHTML = html;
}

/* ── 评级映射 ── */
const levelMap = {
  critical: { icon: '🔴', text: '紧急修复', cls: 'critical' },
  warn:     { icon: '🟡', text: '待优化',   cls: 'warn' },
  pass:     { icon: '🟢', text: '良好',     cls: 'pass' },
};

function getLevel(rating) {
  const r = asString(rating, 'warn').toLowerCase();
  if (r === 'critical' || r === 'p0') return levelMap.critical;
  if (r === 'pass'     || r === 'ok' || r === 'good') return levelMap.pass;
  return levelMap.warn;
}

function getLevelCls(score) {
  if (score >= 80) return 'pass';
  if (score >= 50) return 'warn';
  return 'critical';
}

/* ── 综合评分 ── */
function renderScore() {
  const score = reportData?.meta?.score;
  if (score == null) return;

  const num = Math.round(Number(score));
  const cls = getLevelCls(num);

  const circle = document.getElementById('score-circle');
  if (circle) circle.classList.add(cls);
  setText('score-num', num);
}

/* ── 四维评级徽章 ── */
function renderDimensionScores() {
  const dims = safeArray(reportData?.dimensions);
  const container = document.getElementById('dimension-scores');
  if (!container) return;

  container.innerHTML = dims.map(dim => {
    const lv = getLevel(dim.rating);
    return `<div class="dim-badge level-${lv.cls}">
      <span class="dim-name">${asString(dim.name)}</span>
      <span class="dim-level">${lv.icon} ${lv.text}</span>
    </div>`;
  }).join('');
}

/* ── 总体评级表格 ── */
function renderOverviewTable() {
  const dims = safeArray(reportData?.dimensions);
  const tbody = document.querySelector('#overview-table tbody');
  if (!tbody) return;

  tbody.innerHTML = dims.map(dim => {
    const lv = getLevel(dim.rating);
    return `<tr>
      <td><strong>${asString(dim.name)}</strong></td>
      <td>
        <span class="level-icon">${lv.icon}</span>
        <span class="level-text ${lv.cls}">${lv.text}</span>
      </td>
      <td>${asString(dim.summary, '—')}</td>
    </tr>`;
  }).join('');
}

/* ── 问题列表通用渲染 ── */
function renderIssueList(listId, countId, issues) {
  const container = document.getElementById(listId);
  const countEl   = document.getElementById(countId);
  if (!container) return;

  if (!issues || issues.length === 0) {
    if (countEl) countEl.textContent = '0 项';
    container.innerHTML = '<p style="color:var(--sub);font-size:13px;">暂无此类问题。</p>';
    return;
  }

  if (countEl) countEl.textContent = `${issues.length} 项`;

  container.innerHTML = issues.map((issue, i) => `
    <div class="issue-item">
      <div class="issue-title">${i + 1}. ${asString(issue.title)}</div>
      <div class="issue-row">
        <span class="issue-key">现状</span>
        <span class="issue-val">${asString(issue.current, '未提供')}</span>
      </div>
      <div class="issue-row">
        <span class="issue-key">影响</span>
        <span class="issue-val">${asString(issue.impact, '未提供')}</span>
      </div>
      <div class="issue-row">
        <span class="issue-key">建议</span>
        <span class="issue-val">${asString(issue.suggestion, '未提供')}</span>
      </div>
    </div>
  `).join('');
}

/* ── 已通过检查项 ── */
function renderPassed() {
  const passed = safeArray(reportData?.passed);
  const countEl = document.getElementById('passed-count');
  if (countEl) countEl.textContent = `${passed.length} 项`;

  const ul = document.getElementById('passed-list');
  if (!ul) return;

  ul.innerHTML = passed.length === 0
    ? '<li>暂无已通过的检查项</li>'
    : passed.map(item => `<li>${asString(item)}</li>`).join('');
}

/* ── 行动清单 ── */
function renderChecklist() {
  const items = safeArray(reportData?.checklist);
  const ol = document.getElementById('checklist');
  if (!ol) return;

  ol.innerHTML = items.length === 0
    ? '<li>暂无行动清单项</li>'
    : items.map(item => {
        const priority = asString(item.priority, 'p1').toLowerCase();
        const label    = priority === 'p0' ? 'P0' : 'P1';
        return `<li><span class="priority ${priority}">${label}</span>${asString(item.action)}</li>`;
      }).join('');
}

/* ── 主渲染入口 ── */
(function bootstrap() {
  const meta   = reportData?.meta   || {};
  const issues = reportData?.issues || {};

  // Header
  setText('report-domain', meta.domain, '未知域名');
  setText('report-time', meta.generatedAt ? `诊断时间：${meta.generatedAt}` : '');
  setText('footer-id',   meta.reportId   ? `报告编号：${meta.reportId}` : '');

  // Score & dimensions
  renderScore();
  renderDimensionScores();
  renderOverviewTable();

  // Issues
  renderIssueList('critical-list',    'critical-count',    safeArray(issues.critical));
  renderIssueList('suggestions-list', 'suggestions-count', safeArray(issues.suggestions));

  // Passed & checklist
  renderPassed();
  renderChecklist();

  // 无 critical 时隐藏节点
  if (!safeArray(issues.critical).length) {
    const sec = document.getElementById('section-critical');
    if (sec) sec.style.display = 'none';
  }
})();

